import{_ as t,o as s,c as r,ah as a}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Site transfers","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/secretariat/transferts-sites.md","filePath":"src/en/guide/secretariat/transferts-sites.md"}'),o={name:"en/guide/secretariat/transferts-sites.md"};function n(i,e,h,c,l,p){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="site-transfers" tabindex="-1">Site transfers <a class="header-anchor" href="#site-transfers" aria-label="Permalink to &quot;Site transfers&quot;">​</a></h1><p>A parent can request, from their own account, to transfer their child from one of the school&#39;s sites to another (for example, from one campus to another). The <strong>Inter-site transfers</strong> page lists these requests and lets you carry them through. A request must be approved by both the origin site and the destination site before the transfer takes effect — you play both roles, except for a site that has a <strong>site director</strong>: they then approve that site&#39;s side (see <a href="/era-guide/en/guide/direction/">Direction</a>). Its block reads <strong>Waiting for this site&#39;s approval</strong>, and you can only reject the request if one of the two sites is yours to approve.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This page covers only <strong>student</strong> transfers between two sites. Staff transfers between sites are a separate feature, reserved for administrators.</p></div><h2 id="viewing-the-queue" tabindex="-1">Viewing the queue <a class="header-anchor" href="#viewing-the-queue" aria-label="Permalink to &quot;Viewing the queue&quot;">​</a></h2><p>The page shows, for each request, the student concerned, the origin site, the destination site, and the status (<strong>Pending</strong>, <strong>Approved</strong>, or <strong>Rejected</strong>). Use the status filter to see only the requests you care about, then click <strong>Review</strong> to open one.</p><h2 id="reviewing-a-request" tabindex="-1">Reviewing a request <a class="header-anchor" href="#reviewing-a-request" aria-label="Permalink to &quot;Reviewing a request&quot;">​</a></h2><p>The detail page shows who <strong>requested</strong> the transfer, the <strong>origin site</strong>, the <strong>destination site</strong>, the desired <strong>department</strong> on the new site, and, if one was given, the <strong>reason</strong> for the request.</p><h2 id="approving-a-transfer" tabindex="-1">Approving a transfer <a class="header-anchor" href="#approving-a-transfer" aria-label="Permalink to &quot;Approving a transfer&quot;">​</a></h2><p>The form presents two separate sections, one for each site involved:</p><ol><li>In <strong>Origin site approval</strong>, click <strong>Approve origin</strong>. If this section already shows someone&#39;s name, that site has already given its approval and there&#39;s nothing more to do here.</li><li>In <strong>Destination site approval</strong>, choose the receiving <strong>class</strong> at the new site (each class&#39;s occupancy is shown, for example <code>18/25</code>). If the class has reached its capacity, check <strong>Force assignment even if the class has reached its capacity</strong> to assign it anyway, enter the <strong>Reason for going over capacity</strong>, then click <strong>Approve destination</strong>.</li></ol><p>As soon as both sites have given their approval — in either order — the transfer executes automatically: the student is moved to the new site, department, and class, with no further action on your part.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The notification of a new request (for example on your phone) opens the <a href="/era-guide/en/guide/direction/a-approuver.html">To approve</a> page: it lets you approve your site&#39;s departure or arrival, or reject the request, without navigating the rest of the app.</p></div><div class="info custom-block"><p class="custom-block-title">Capacity overrides</p><p>The reason is required when the class is full. The override is recorded (who, when, headcount, reason) and the site&#39;s direction, the general direction and the administrators are told.</p></div><h2 id="rejecting-a-request" tabindex="-1">Rejecting a request <a class="header-anchor" href="#rejecting-a-request" aria-label="Permalink to &quot;Rejecting a request&quot;">​</a></h2><ol><li>From a pending request&#39;s detail page, click <strong>Reject</strong>.</li><li>Enter the <strong>Rejection reason</strong> (required).</li><li>Confirm by clicking <strong>Reject</strong> again.</li></ol><p>A rejected request can no longer be approved: the family must submit a new one if they want to try again.</p>',16)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
